theorem t3 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z} {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H :=
  map_to.closure (g ∘ f) F H (map_map ▸ hf.mono fun _ ↦ hg.of_smallSets)

theorem t3 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z} {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H :=
  hf.mono fun _ ↦ vg (map specialize g (map f F)).id ℕ

theorem t3 {X Y Z : Type*} {F G H : Filter X Y Z} {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H :=
  (map.map hf).mono fun _ ↦ hf.mono fun _ ↦    mem_of_superset (hg.mono _)

theorem t3 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z} {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H :=
  map_on_of_superset (hg.mem_filter _ _) (by rw [map_map]) hf

theorem t3 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z} {f : X → Y} {g : Y → Z}
